<?php
namespace App\Http\Controllers\Api\V1\Guest;
use App\Http\Controllers\Controller; use App\Models\{Payment,PaymentTransaction,Reservation}; use App\Services\Payments\PaymentManager; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class GuestPaymentController extends Controller { public function initiate(Request $r,Reservation $reservation,PaymentManager $manager){$u=$r->user();abort_unless($u->role==='guest'&&$u->guest_id===$reservation->guest_id,403);$d=$r->validate(['method'=>'required|in:mtn_momo,airtel_momo,pesapal,flutterwave,card,bank_transfer','amount'=>'required|numeric|min:1','phone'=>'nullable|string|max:50']);$paid=(float)$reservation->payments()->where('status','successful')->sum('amount');$outstanding=max(0,(float)$reservation->grand_total-$paid);if((float)$d['amount']>$outstanding+0.009)throw ValidationException::withMessages(['amount'=>'Payment exceeds the reservation outstanding balance.']);$payment=Payment::create(['property_id'=>$reservation->property_id,'guest_id'=>$reservation->guest_id,'reservation_id'=>$reservation->id,'reference'=>'PAY-'.strtoupper(Str::random(12)),'method'=>$d['method'],'gateway'=>in_array($d['method'],['mtn_momo','airtel_momo','pesapal','flutterwave','card'])?$d['method']:null,'status'=>'pending','currency'=>'UGX','amount'=>$d['amount'],'payer_phone'=>$d['phone']??$u->phone,'description'=>'Online reservation payment '.$reservation->reference]);$checkout=['mode'=>'pending'];if($payment->gateway){try{$payload=['reference'=>$payment->reference,'amount'=>(float)$payment->amount,'currency'=>$payment->currency,'phone'=>$payment->payer_phone,'email'=>$u->email,'name'=>$u->name,'first_name'=>$u->guest?->first_name,'last_name'=>$u->guest?->last_name,'description'=>$payment->description,'callback_url'=>url('/api/v1/payments/webhook/'.$payment->gateway)];$checkout=$manager->gateway($payment->gateway)->initiate($payload);$payment->update(['status'=>'processing','gateway_reference'=>$checkout['gateway_reference']??null]);PaymentTransaction::create(['payment_id'=>$payment->id,'gateway'=>$payment->gateway,'gateway_reference'=>$checkout['gateway_reference']??null,'status'=>'processing','request_payload'=>$payload,'response_payload'=>$checkout]);}catch(\Throwable $e){report($e);$checkout=['mode'=>'configuration_required','message'=>$e->getMessage(),'gateway'=>$payment->gateway];}}elseif($d['method']==='bank_transfer'){$checkout=['mode'=>'bank_transfer','message'=>'Use the hotel bank details configured by management and quote '.$payment->reference];}return response()->json(['payment'=>$payment->fresh(),'checkout'=>$checkout,'outstanding_before'=>$outstanding],201);} public function status(Request $r,Payment $payment,PaymentManager $m){abort_unless($r->user()->role==='guest'&&$r->user()->guest_id===$payment->guest_id,403);if($payment->gateway&&in_array((string)($payment->status->value??$payment->status),['pending','processing'],true)&&$payment->gateway_reference){try{$v=$m->gateway($payment->gateway)->verify($payment->gateway_reference);if(($v['successful']??false)&&($v['currency']??$payment->currency)===$payment->currency&&(float)($v['amount']??$payment->amount)+0.01>=(float)$payment->amount)$payment->update(['status'=>'successful','paid_at'=>now()]);}catch(\Throwable $e){report($e);}}return $payment->fresh()->load('transactions');} }
